   node3.X = 120; node3.Y = 140; node3.Z = 130;

   polylineSplinePath3D.AddPoint(node1.Geometry.Point);
   polylineSplinePath3D.AddPoint(node2.Geometry.Point);
   polylineSplinePath3D.AddPoint(node3.Geometry.Point);

   document.EndChanges();//Закрытие блока изменений документа
}

