public static void FragmentTransformation(Operation operation, LCS lcs) { Document document = TFlex.Application.ActiveDocument;//Получение активного документа document.BeginChanges("перемещение"); //Открытие блока изменений документа
FragmentTransformation ft = new FragmentTransformation(document); ft.AddRotation(StandardAxis.AxisX, 30);//поворот вокруг оси X ft.AddRotation(StandardAxis.AxisY, 10);//поворот вокруг оси Y ft.LCS = lcs;//Система координат, относительно которой производится преобразование ft.Offset_X = 100;//Значение свойства перемещения вдоль оси X ft.Offset_Y = 200;//Значение свойства перемещения вдоль оси Y ft.Offset_Z = 300;//Значение свойства перемещения вдоль оси Z operation.VolatileTransformations.Add(ft);//преобразование для операции
document.EndChanges();//Закрытие блока изменений документа }

