public static void AreaProfile()
{
   Document document = TFlex.Application.ActiveDocument;//Получение активного документа
   document.BeginChanges("профиль по штриховке");//Открытие блока изменений документа

   FreeNode n1 = new FreeNode(document,50,50);

   //создание окружности через центр и радиус 
   CircleConstruction circle = new CircleConstruction (document);
   circle.SetCenterAndRadius(n1, 10); 
   //создание штриховки

   Area ar = new Area (document); 
   TFlex.Model.Model2D.Contour cn = ar.AppendContour(); 

   //добавление в контур окружности
   ConstructionContourSegment seg1 = new ConstructionContourSegment(cn); 
   seg1.Construction = circle;

   //построение профиля
   StandardWorkplane swp = new StandardWorkplane(document, StandardWorkplane.StandardType.Left); 
   AreaProfile areaProfile = new AreaProfile(document); 
   areaProfile.Area = ar; //профиль по штриховке
   areaProfile.WorkSurface = swp;//Рабочая поверхность, задающая ориентацию профиля

   document.EndChanges();//Закрытие блока изменений документа
}

public static void AreaProfile()
{
   Document doc = TFlex.Application.ActiveDocument;
   doc.BeginChanges("Создание профиля");
   Page pg_XY = new Page(doc);
   pg_XY.Properties.Lines.ThicknessRepresentation = TFlex.Configuration.LineThicknessRepresentation.AlwaysThreePixels;
   pg_XY.Properties.Lines.ConstructionsDrawLast = true;

   pg_XY.Name = "LW-PL_" + 1.ToString();
   pg_XY.PageType = PageType.Workplane;

   StandardWorkplane wp_XY = new StandardWorkplane(doc, StandardWorkplane.StandardType.Top);
   wp_XY.Name = "LW-PL_" + 1.ToString();
   wp_XY.ShowOn3D = true;
   wp_XY.Page = pg_XY;

   Area ar = new Area(doc);
   ar.FillStyle = AreaFillStyle.Fill;
   ar.Color = 2;
   ar.Page = pg_XY;
   TFlex.Model.Model2D.Contour contour = ar.AppendContour();


   FreeNode first = new FreeNode(doc);
   first.Page = pg_XY;
   first.X = 10;
   first.Y = 10;

   Outline ln = new CircleOutline(doc, first, 25);

   OutlineContourSegment seg = new OutlineContourSegment(contour);
   seg.Outline = ln;

   AreaProfile prof = new AreaProfile(doc);
   prof.Area = ar;
   prof.WorkSurface = wp_XY;

   CoordinateNode3D nd3 = new CoordinateNode3D(doc);
   nd3.X = 20 * 1.000;
   nd3.Y = 30 * 1.000;
   nd3.Z = 40 * 1.000;
   nd3.Color = 7;

   prof.OnHatch = (Node)first;
   prof.Target = (Node3D)nd3;
   doc.EndChanges();
}

public static void SketchProfile()
{
   Document document = TFlex.Application.ActiveDocument;//Получение активного документа
   document.BeginChanges("Профиль, построенный по эскизу");//Открытие блока изменений документа

   //создание узлов		
   FreeNode fn1 = new FreeNode(document, 10, 10);
   FreeNode fn2 = new FreeNode(document, 40, 30);
   FreeNode fn3 = new FreeNode(document, 70, 10);

   //создание линий, проходящих через эти узлы		
   ConstructionOutline l1 = new ConstructionOutline(document, fn1, fn2);
   ConstructionOutline l2 = new ConstructionOutline(document, fn2, fn3);
   ConstructionOutline l3 = new ConstructionOutline(document, fn3, fn1);

   //рабочая плоскость(вид слева), на которой будет построен профиль		
   StandardWorkplane swp = new StandardWorkplane(document, StandardWorkplane.StandardType.Left); 
   SketchProfile sp = new SketchProfile(document);
   sp.WorkSurface = swp;

   document.EndChanges();//Закрытие блока изменений документа
}

